import { Component, computed, input } from '@angular/core';

export type AppIconName =
  | 'home'
  | 'grades'
  | 'absences'
  | 'timetable'
  | 'events'
  | 'messages'
  | 'homework'
  | 'behavior'
  | 'payments'
  | 'admin'
  | 'school'
  | 'logs';

/** Agenda icon from `public/images/icons/` (generated by
 * `tools/generate-icons.py`). Rendered as a CSS mask filled with
 * `--soovioo-icon-color` (logo navy, white in dark mode — see styles.scss),
 * so it follows the theme like the logo does. Sized in `em`: set the
 * size through the host's font-size (e.g. `class="text-2xl"`). Purely
 * decorative — always sits next to a visible text label. */
@Component({
  selector: 'app-icon',
  template: '',
  host: {
    class: 'soovioo-icon',
    'aria-hidden': 'true',
    '[style.--soovioo-icon-url]': 'url()',
  },
})
export class AppIcon {
  readonly name = input.required<AppIconName>();

  protected readonly url = computed(
    () => `url("/images/icons/${this.name()}.svg")`,
  );
}
